import torch
import torch.nn as nn

from cutegen.ptx_runtime import PtxModule, i32, i64, u32, u64, f32, f64

PTX_SOURCE = r"""
.version 8.7
.target sm_89
.address_size 64

.visible .entry min_reduce_kernel(
    .param .u64 param_X,
    .param .u64 param_Y,
    .param .u32 param_Outer,
    .param .u32 param_Reduce,
    .param .u32 param_Inner
)
{
    .reg .pred %p<8>;
    .reg .f32 %f<8>;
    .reg .b32 %r<24>;
    .reg .b64 %rd<24>;

    ld.param.u64 %rd1, [param_X];
    ld.param.u64 %rd2, [param_Y];
    ld.param.u32 %r1, [param_Outer];
    ld.param.u32 %r2, [param_Reduce];
    ld.param.u32 %r3, [param_Inner];

    cvta.to.global.u64 %rd3, %rd1;
    cvta.to.global.u64 %rd4, %rd2;

    // total = outer * inner  (flattened output element count)
    mul.lo.s32 %r4, %r1, %r3;

    // idx = blockIdx.x * blockDim.x + threadIdx.x
    mov.u32 %r5, %ctaid.x;
    mov.u32 %r6, %ntid.x;
    mov.u32 %r7, %tid.x;
    mad.lo.s32 %r8, %r5, %r6, %r7;

    // stride = gridDim.x * blockDim.x  (grid-stride loop)
    mov.u32 %r9, %nctaid.x;
    mul.lo.s32 %r10, %r9, %r6;

LOOP_START:
    setp.ge.s32 %p1, %r8, %r4;
    @%p1 bra DONE;

    // outer_idx = idx / inner ; inner_idx = idx % inner
    div.s32 %r11, %r8, %r3;
    rem.s32 %r12, %r8, %r3;

    cvt.s64.s32 %rd5, %r11;   // outer_idx
    cvt.s64.s32 %rd6, %r2;    // Reduce
    cvt.s64.s32 %rd7, %r3;    // Inner
    cvt.s64.s32 %rd8, %r12;   // inner_idx

    // base element index = outer_idx * Reduce * Inner + inner_idx
    mul.lo.s64 %rd9, %rd5, %rd6;
    mul.lo.s64 %rd10, %rd9, %rd7;
    add.s64 %rd11, %rd10, %rd8;
    shl.b64 %rd12, %rd11, 2;
    add.s64 %rd13, %rd3, %rd12;     // pointer to X[outer,0,inner]

    // stride in bytes between consecutive reduce steps = Inner * 4
    shl.b64 %rd14, %rd7, 2;

    ld.global.f32 %f1, [%rd13];     // minval = X[outer,0,inner]

    mov.u32 %r13, 1;

INNER_LOOP_COND:
    setp.ge.s32 %p2, %r13, %r2;
    @%p2 bra INNER_LOOP_END;

    add.s64 %rd13, %rd13, %rd14;
    ld.global.f32 %f2, [%rd13];
    min.f32 %f1, %f1, %f2;
    add.s32 %r13, %r13, 1;
    bra INNER_LOOP_COND;

INNER_LOOP_END:
    // output flattened index equals idx directly (outer_idx*Inner + inner_idx)
    cvt.s64.s32 %rd15, %r8;
    shl.b64 %rd16, %rd15, 2;
    add.s64 %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f1;

    add.s32 %r8, %r8, %r10;
    bra LOOP_START;

DONE:
    ret;
}
"""

_module = None


def _get_module():
    global _module
    if _module is None:
        _module = PtxModule(PTX_SOURCE)
    return _module


def validate_generated_code():
    module = _get_module()
    module.function("min_reduce_kernel")
    return module


class ModelNew(nn.Module):
    """
    Simple model that performs min reduction over a specific dimension,
    implemented with a hand-authored PTX kernel launched via PtxModule.

    Optimization applied: replaced the 2D (outer, inner)-indexed launch
    configuration with a 1D grid-stride loop over the flattened output
    element space. The grid size is now rounded up to a whole number of
    "full waves" (SM count * achievable resident blocks per SM) so the
    kernel launch avoids a trailing partial wave, which the profiler
    identified as accounting for a significant fraction of the previous
    kernel's runtime.
    """

    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self._module = _get_module()
        self._module.function("min_reduce_kernel")

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "x must be a CUDA tensor"
        assert x.dtype == torch.float32, "x must be float32"

        ndim = x.dim()
        dim = self.dim
        if dim < 0:
            dim += ndim
        assert 0 <= dim < ndim, "dim out of range"

        x_c = x.contiguous()

        outer = 1
        for i in range(dim):
            outer *= x_c.shape[i]
        reduce = x_c.shape[dim]
        inner = 1
        for i in range(dim + 1, ndim):
            inner *= x_c.shape[i]

        out_shape = [x_c.shape[i] for i in range(ndim) if i != dim]
        y = torch.empty(out_shape, device=x_c.device, dtype=x_c.dtype)

        total = outer * inner
        threads = 256

        # Determine a grid size that is an exact multiple of a "full wave"
        # (number of SMs times the number of blocks that can concurrently
        # reside per SM for this kernel's register/thread footprint), so
        # that the launch does not end with a partial (tail) wave.
        try:
            sm_count = torch.cuda.get_device_properties(x_c.device).multi_processor_count
        except Exception:
            sm_count = 128  # reasonable fallback for target GPU

        blocks_per_sm = 6  # matches this kernel's occupancy (256 threads/block, ~30 regs/thread -> 1536 threads/SM cap)
        full_wave = max(1, sm_count * blocks_per_sm)

        min_blocks_needed = max(1, (total + threads - 1) // threads)
        num_waves = max(1, (min_blocks_needed + full_wave - 1) // full_wave)
        grid_blocks = num_waves * full_wave

        # Safety cap for grid.x (well within CUDA's limit, keeps launch sane)
        grid_blocks = min(grid_blocks, 2**31 - 1)

        stream = torch.cuda.current_stream().cuda_stream

        self._module.launch(
            "min_reduce_kernel",
            grid=(grid_blocks, 1, 1),
            block=(threads, 1, 1),
            args=[
                i64(x_c.data_ptr()),
                i64(y.data_ptr()),
                i32(outer),
                i32(reduce),
                i32(inner),
            ],
            stream=stream,
        )

        return y

